"""Active renderer and real ordinary-task fixtures. Never claim these as organic story events."""
from test_expedition_integration import ExpeditionIntegration
class VisualIntegration(ExpeditionIntegration):
 def test_visual_live_primary_and_previews_use_new_art_without_mutating_world(self):
  p=self.page();self.operations(p);p.locator('#camera-scene').scroll_into_view_if_needed();before=self.snap(p);self.assertEqual(p.evaluate('ICARUSPixelCamera.version'),2);p.locator('.obs-select').select_option('A09');p.evaluate('ICARUSObservationLive.camera.draw(true)');first=p.evaluate('document.querySelector("#observation-primary").toDataURL()');p.locator('.obs-select').select_option('A08');p.evaluate('ICARUSObservationLive.camera.draw(true)');self.assertNotEqual(first,p.evaluate('document.querySelector("#observation-primary").toDataURL()'));self.assertGreater(p.evaluate('ICARUSRoomArt.metrics.builds'),1);self.assertGreater(p.evaluate('ICARUSRoomArt.metrics.hits'),0);self.assertEqual(self.snap(p),before);self.assertGreater(p.evaluate('ICARUSObservationLive.camera.stats.previewFrames'),0)
 def test_visual_saved_appearance_and_old_voyage_fields_migrate_exactly(self):
  p=self.page();before=self.snap(p);self.assertTrue(all(q['visualAppearance']['version']==1 for q in before['crew']));p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),before);self.configure(p,'delete s.crew[0].visualAppearance;');after=self.snap(p);self.assertEqual(after['crew'][0]['visualAppearance'],before['crew'][0]['visualAppearance']);self.assertEqual(after['crew'][0]['memories'],before['crew'][0]['memories']);self.assertEqual(after['crew'][0]['relationships'],before['crew'][0]['relationships'])
 def test_visual_lounge_approach_seating_and_rise_are_actual_tasks(self):
  p=self.page();self.configure(p,"s.remoteCore.autonomyEnabled=false;const q=s.crew[0];q.room=q.target='A09';q.route=[];q.nav=null;q.task=q.goal='Taking a recreation break';q.taskMinutes=12;q.interaction='working';q.energy=90;");self.advance(p,1);s=self.snap(p);self.assertEqual(s['crew'][0]['taskMinutes'],12);self.assertEqual(s['crew'][0]['roomInteraction']['phase'],'approaching');self.advance(p,10);s=self.snap(p);self.assertLess(s['crew'][0]['taskMinutes'],12);v=p.evaluate('__icarusSoak.observation().rooms.find(r=>r.id==="A09").actors.find(p=>p.name==="Frank Morrow")');self.assertTrue(v['seated']);self.assertEqual(v['fixture'],'SOFA-R');self.assertEqual(p.evaluate('ICARUSCharacterDesign.geometry(__icarusSoak.observation().rooms.find(r=>r.id==="A09").actors.find(p=>p.name==="Frank Morrow")).seated'),True);before=s;p.evaluate('__icarusSoak.save()');p.reload();self.assertEqual(self.snap(p),before);self.advance(p,20);self.assertNotEqual(self.snap(p)['crew'][0].get('roomInteraction',{}).get('phase'),'rising')
 def test_visual_wheelchair_real_approach_turn_and_seated_geometry(self):
  p=self.page();self.configure(p,"s.remoteCore.autonomyEnabled=false;const q=s.crew[0];q.room=q.target='A09';q.route=[];q.nav=null;q.task=q.goal='Taking a recreation break';q.taskMinutes=20;q.interaction='working';q.energy=90;q.body={...(q.body||{}),locomotion:'wheelchair'};q.roomPlacement={room:'A09',x:320,y:195};");self.advance(p,1);q=self.snap(p)['crew'][0];self.assertEqual(q['roomInteraction']['phase'],'turning');view=p.evaluate('__icarusSoak.observation().rooms.find(r=>r.id==="A09").actors.find(p=>p.name==="Frank Morrow")');self.assertEqual(view['state'],'turn');self.assertEqual(view['facing'],-1);self.advance(p,1);view=p.evaluate('__icarusSoak.observation().rooms.find(r=>r.id==="A09").actors.find(p=>p.name==="Frank Morrow")');self.assertEqual(view['state'],'roll');self.assertTrue(view['moving']);self.assertTrue(p.evaluate('ICARUSCharacterDesign.geometry(__icarusSoak.observation().rooms.find(r=>r.id==="A09").actors.find(p=>p.name==="Frank Morrow")).wheelchair'));self.advance(p,15);self.assertEqual(self.snap(p)['crew'][0]['roomInteraction']['y'],195);self.assertEqual(self.snap(p)['transitAudit'],[])
 def test_visual_power_sensitive_art_cache_and_private_rooms_are_preserved(self):
  p=self.page();before=self.snap(p);r=p.evaluate('''()=>{const c=document.createElement('canvas'),r=__icarusSoak.observation().rooms.find(r=>r.id==='A09');ICARUSPixelCamera.draw(c,r,{paused:true});const a=c.toDataURL(),n=ICARUSRoomArt.metrics.builds;ICARUSPixelCamera.draw(c,{...r,lighting:0},{paused:true});return {a,b:c.toDataURL(),n,after:ICARUSRoomArt.metrics.builds};}''');self.assertNotEqual(r['a'],r['b']);self.assertGreater(r['after'],r['n']);self.assertFalse(p.evaluate('__icarusSoak.observation().rooms.find(r=>r.id==="A05").available'));self.assertEqual(self.snap(p),before)
 def test_visual_boot_ready_is_real_and_ordinary_clock_remains_separate(self):
  p=self.page();p.wait_for_function('ICARUSBoot.complete');self.assertTrue(p.locator('#icarus-boot').is_hidden());self.assertTrue(all(s['state']=='ready' for s in p.evaluate('ICARUSBoot.states').values()));before=self.snap(p);p.locator('#boot-status-toggle').click();self.assertIn('ICARUS ONLINE',p.locator('.boot-status').inner_text());p.keyboard.press('Escape');self.assertEqual(self.snap(p),before)
